zig_test:
test "t13 arraylist evens" {
    const xs = [_]i32{ 1, 2, 3, 4, -6, 7 };
    const got = try collectEvens(std.testing.allocator, &xs);
    defer std.testing.allocator.free(got);
    try std.testing.expectEqualSlices(i32, &.{ 2, 4, -6 }, got);
    const none = try collectEvens(std.testing.allocator, &.{ 1, 3 });
    defer std.testing.allocator.free(none);
    try std.testing.expectEqual(@as(usize, 0), none.len);
}
